const extractSheetId = (urlOrId = "") => {
  if (!urlOrId) return "";
  if (!urlOrId.includes("docs.google.com")) return urlOrId.trim();
  const parts = urlOrId.split("/d/");
  if (parts.length < 2) return urlOrId.trim();
  return parts[1].split("/")[0];
};
